import {
  mediaPath,
  widthsFor,
  type BlogPost,
  type BlogPostSummary,
  type ContentSnapshot,
  type PublicImage,
  type SnapshotArticle,
  type SnapshotLocale,
  type SnapshotMedia,
} from "../../domain/blog";
import { mediaIdsOf, readingMinutes } from "../../features/blog/document";
import { localeInfo, type Locale } from "../../i18n/config";
import { formatDate } from "../../i18n/format";
import type { BlogEntry, BlogRepository } from "../repositories";

/** Responsive variants generated by scripts/studio/process-media.mjs. */
export function toPublicImage(media: SnapshotMedia, alt: string): PublicImage {
  const widths = widthsFor(media.width);
  const largest = widths.at(-1)!;
  return {
    id: media.id,
    width: largest,
    height: Math.round((media.height * largest) / media.width),
    alt,
    src: mediaPath(media.id, largest),
    srcSet: widths.map((width) => `${mediaPath(media.id, width)} ${width}w`).join(", "),
  };
}

type Found = { article: SnapshotArticle; draft: SnapshotLocale };

export function createSnapshotBlogRepository(load: () => ContentSnapshot): BlogRepository {
  function context() {
    const snapshot = load();
    const media = new Map(snapshot.media.map((item) => [item.id, item]));
    // The API sends newest first; sorting again keeps the order explicit.
    const articles = [...snapshot.articles].sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
    return { articles, media };
  }

  function image(media: Map<string, SnapshotMedia>, id: string | null | undefined, locale: Locale, alt?: string) {
    const item = id ? media.get(id) : undefined;
    if (!item) return null;
    return toPublicImage(item, alt || item.alt[locale] || "");
  }

  function summary({ article, draft }: Found, media: Map<string, SnapshotMedia>): BlogPostSummary {
    const tag = localeInfo[draft.locale].tag;
    return {
      id: article.id,
      type: article.type,
      locale: draft.locale,
      slug: draft.slug,
      title: draft.title,
      excerpt: draft.excerpt,
      tags: article.tags,
      publishedAt: article.publishedAt,
      updatedAt: article.updatedAt,
      publishedLabel: formatDate(article.publishedAt, tag),
      readingMinutes: readingMinutes(draft.content),
      cover: image(media, article.coverMediaId, draft.locale),
    };
  }

  function inLocale(articles: SnapshotArticle[], locale: Locale): Found[] {
    return articles.flatMap((article) => {
      const draft = article.locales.find((candidate) => candidate.locale === locale);
      return draft ? [{ article, draft }] : [];
    });
  }

  return {
    async list(locale) {
      const { articles, media } = context();
      return inLocale(articles, locale).map((found) => summary(found, media));
    },

    async findBySlug(slug, locale) {
      const { articles, media } = context();
      const found = inLocale(articles, locale).find(({ draft }) => draft.slug === slug);
      if (!found) return undefined;
      const { article, draft } = found;

      const images: Record<string, PublicImage> = {};
      for (const id of mediaIdsOf(draft.content)) {
        const item = image(media, id, locale);
        if (item) images[id] = item;
      }
      const post: BlogPost = {
        ...summary(found, media),
        seoTitle: draft.seoTitle || draft.title,
        seoDescription: draft.seoDescription || draft.excerpt,
        ogImage: image(media, draft.ogMediaId, locale) ?? image(media, article.coverMediaId, locale),
        updatedLabel: formatDate(article.updatedAt, localeInfo[locale].tag),
        content: draft.content,
        images,
        alternates: Object.fromEntries(article.locales.map((other) => [other.locale, other.slug])),
      };
      if (draft.canonicalUrl) post.canonicalUrl = draft.canonicalUrl;
      return post;
    },

    async findMovedSlug(slug, locale) {
      const { articles } = context();
      return inLocale(articles, locale).find(({ draft }) => draft.previousSlugs.includes(slug))?.draft.slug;
    },

    async entries() {
      const { articles } = context();
      const current = new Set(articles.flatMap((article) => article.locales.map((draft) => `${draft.locale}/${draft.slug}`)));
      return articles.flatMap((article): BlogEntry[] => {
        const translations = Object.fromEntries(article.locales.map((draft) => [draft.locale, draft.slug]));
        return article.locales.map((draft) => ({
          id: article.id,
          locale: draft.locale,
          slug: draft.slug,
          // Never a redirect over a page that exists.
          previousSlugs: draft.previousSlugs.filter((slug) => !current.has(`${draft.locale}/${slug}`)),
          updatedAt: article.updatedAt,
          translations,
        }));
      });
    },
  };
}
